mapper.select:
SELECT
    ic.integrated_customer_id AS integratedCustomerId,
    ic.name AS name,
    ic.birth_date AS birthDate,
    -- 화면에서 선택한 관계 코드(01=부, 02=모)를 그대로 응답에 포함
    #{request.relationshipCode} AS relationshipCode,
    -- 관계 코드명을 common_code에서 조회하여 부/모로 내려줌
    cc.code_name AS relationshipName,
    ic.phone AS phone,
    ic.address AS address
FROM integrated_customer ic
-- relationshipCode의 코드명을 가져오기 위한 메타코드 조인
INNER JOIN common_code cc
    ON cc.group_code = 'RELATIONSHIP'
    AND cc.code_value = #{request.relationshipCode}
WHERE ic.name = #{request.name}
    AND ic.birth_date = #{request.birthDate}
    AND ic.gender = #{gender}
    AND ic.phone = #{request.phone}
    AND ic.rrn_encrypted = #{hashedRrn}
    AND ic.address = #{request.address}
    AND ic.sales_user_id = #{salesUserId}

LIMIT 1

SELECT COUNT(*) > 0
FROM integrated_customer
WHERE integrated_customer_id = #{parentCustomerId}

SELECT COUNT(*) > 0
FROM potential_customer
WHERE parent_customer_id = #{parentCustomerId}
    AND name = #{name}
    AND gender = #{gender}
    AND birth_date = #{birthDate}

SELECT COUNT(*) > 0
FROM potential_customer
WHERE id = #{potentialCustomerId}
    AND sales_user_id = #{salesUserId}
